package com.netbanking.account.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="ACCOUNT_LEDGER") public class AccountLedger {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="LEDGER_ID") private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="ACCOUNT_ID",nullable=false) private Account account;
 @Column(name="TRANSACTION_REFERENCE",nullable=false) private String transactionReference; @Column(name="ENTRY_REFERENCE",nullable=false,unique=true) private String entryReference; @Enumerated(EnumType.STRING) @Column(name="ENTRY_TYPE",nullable=false) private EntryType entryType; @Column(nullable=false) private BigDecimal amount; @Column(name="BALANCE_BEFORE",nullable=false) private BigDecimal balanceBefore; @Column(name="BALANCE_AFTER",nullable=false) private BigDecimal balanceAfter; @Column(name="AVAILABLE_BALANCE_BEFORE",nullable=false) private BigDecimal availableBalanceBefore; @Column(name="AVAILABLE_BALANCE_AFTER",nullable=false) private BigDecimal availableBalanceAfter; private String description; @Column(name="CREATED_BY") private String createdBy; @Column(name="CREATED_AT",updatable=false) private LocalDateTime createdAt;
 protected AccountLedger(){} public AccountLedger(Account a,String tx,String entry,EntryType type,BigDecimal amount,BigDecimal before,BigDecimal after,BigDecimal availableBefore,BigDecimal availableAfter,String description,String by){account=a;transactionReference=tx;entryReference=entry;entryType=type;this.amount=amount;balanceBefore=before;balanceAfter=after;availableBalanceBefore=availableBefore;availableBalanceAfter=availableAfter;this.description=description;createdBy=by;} @PrePersist void onCreate(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;} public String getTransactionReference(){return transactionReference;} public String getEntryReference(){return entryReference;} public EntryType getEntryType(){return entryType;} public BigDecimal getAmount(){return amount;} public BigDecimal getBalanceAfter(){return balanceAfter;} public LocalDateTime getCreatedAt(){return createdAt;}
}
